import java.util.concurrent.locks.*;

final class Account {
    private final Lock lock = new ReentrantLock();
    private int balance;

    Account(int balance) { this.balance = balance; }

    void deposit(int amount) {
        lock.lock();
        try {
            if (amount <= 0) throw new IllegalArgumentException();
            balance += amount;
        } finally {
            lock.unlock();
        }
    }

    int balance() {
        lock.lock();
        try { return balance; }
        finally { lock.unlock(); }
    }
}

